 skillIssue(id){const s=this.ship(id);if(!s||s.hp<=0)return '戦闘不能';if(s.skillCd>0)return `再使用 ${Math.ceil(s.skillCd)}秒`;if(id==='stake'&&this.concentration(this.enemy)<.06)return '敵の足元に血域が必要';if(id==='lance'&&this.joust)return 'ジョスト実行中';return ''}
