 travel(s,p,speed,dt){const d=distance(s,p),n=Math.min(d,speed*dt);if(d>1){s.x+=(p.x-s.x)/d*n;s.y+=(p.y-s.y)/d*n;s.angle=Math.atan2(p.y-s.y,p.x-s.x)}s.speedNow=dt?n/dt:0;return d}
 move(s,dt){if(s.windup||s.lunge)return;if(s.id==='lance'&&this.joust){const j=this.joust;j.age+=dt;if(j.age>16){this.joust=null;this.timing=null;this.log('ジョストを中断：進路を再確認。');return}if(j.phase==='approach'){if(this.travel(s,j.entry,115,dt)<8)j.phase='charge';s.status='助走位置へ';}else if(j.phase==='charge'){j.speed=Math.min(240,j.speed+100*dt);s.status=`ジョスト 加速 ${Math.round(j.speed)}`;if(distance(s,this.enemy)>105)this.travel(s,this.enemy,j.speed,dt);else{j.phase='timing';this.timing={progress:0,pressed:false,bonus:1};this.lastTiming='';}}else s.status='射出集中';return}this.travel(s,this.destination(s),s.speed*ORDERS[this.order].speed,dt);s.angle=Math.atan2(this.enemy.y-s.y,this.enemy.x-s.x)}
 hitEnemy(damage,kind,owner){if(this.mode==='ended')return;const e=this.enemy,value=Math.round(damage);this.stats.dealt[kind]=(this.stats.dealt[kind]||0)+Math.min(value,e.hp);e.hp=Math.max(0,e.hp-value);e.hitUntil=this.time+.22;const color=kind==='stake'?'#9ce9d7':kind==='lance'?'#f9d68c':'#f28da0';this.label(e.x,e.y-75,`${kind==='stake'?'杭':kind==='lance'?'巨槍':'失血'} −${value}`,color);if(kind!=='bleed')this.effect('impact',e.x,e.y,{color,size:kind==='lance'?75:34});if(kind==='stake'){e.bleed=Math.min(5,e.bleed+1+Math.floor(owner.blood/25));e.bleedUntil=this.time+12}if(e.hp<=0){this.finish(true);return}if(e.form===1&&e.hp<=e.maxHp*.5){e.form=2;this.queuePause('ネフェリム、第二形態','薙ぎ払いが強化されました。予兆範囲を確認してください。',8)}}
