 enemyWindup(){const e=this.enemy,living=this.ships.filter(s=>s.hp>0);if(!living.length)return;if(this.slamNext()){const feed=s=>this.concentration(s)+distance(s,e)/5000,target=living.reduce((a,b)=>feed(a)>=feed(b)?a:b);e.attack={type:'slam',x:target.x,y:target.y,angle:e.angle,range:115,arc:Math.PI,age:0,duration:3.4,targetId:target.id};e.attackCount++;this.queuePause('血潮の墜落の予兆',`${target.name}の足元に赤い円。血を吸う艦が狙われます。集合で円の外へ逃がすか、防護で耐えて。円内の血域は敵に吸い上げられます。`,5);return}const g=this.ship('guard'),target=(g.hp>0&&distance(g,e)<330)?g:living.reduce((a,b)=>distance(a,e)<distance(b,e)?a:b);if(distance(target,e)>255)return;const angle=Math.atan2(target.y-e.y,target.x-e.x);e.angle=angle;e.attack={type:'sweep',x:e.x,y:e.y,angle,range:265,arc:1.12,age:0,duration:2.7,targetId:target.id};e.attackCount++;this.queuePause('薙ぎ払いの予兆','赤い扇形が攻撃範囲。集合で回避、または不退の誓いで耐えて反撃。',4)}
